/* Fűtéstuning custom Home Assistant Lovelace card, v0.3.1 */
const DATA={
 buffer:"sensor.elite_thr316d_sonoff_1002bdc9e4_temperature",
 alert:"binary_sensor.hideg_puffer_futesi_igeny_van",
 circuits:[
 ["Pince","sensor.wifi_rs_beepitett_szelep_1_homerseklet","number.wifi_rs_futeskor_1_szelep_beallitott_hom","switch.pince_szivattyu_mini_d"],
 ["Padlófűtés","sensor.wifi_rs_beepitett_szelep_2_homerseklet","number.wifi_rs_futeskor_2_szelep_beallitott_hom","switch.padlo_szivattyu_mini_d"],
 ["Radiátor","sensor.wifi_rs_beepitett_szelep_3_homerseklet","number.wifi_rs_futeskor_3_szelep_beallitott_hom","switch.radiator_szivattyu_mini_d"]
 ],
 rooms:[
 ["Emelet","Gréta háló","sensor.greta_radiator_temperature","climate.greta_radiator"],
 ["Emelet","Emeleti fürdő","sensor.emeleti_furdo_homero_temperature",null],
 ["Emelet","Flóra háló","sensor.flora_homero_temperature",null],
 ["Földszint","Szülői háló",null,null],
 ["Földszint","Dolgozó","sensor.dolgozo_homero_temperature","climate.dolgozo_radiator"],
 ["Földszint","Földszinti fürdő","sensor.foldszinti_furdo_radiator_temperature","climate.foldszinti_furdo_radiator"],
 ["Földszint","Hanna háló","sensor.hanna_homero_temperature",null],
 ["Földszint","Nappali / konyha / étkező","sensor.nappali_homero_temperature",null],
 ["Földszint","Garázs","sensor.garazs_homero_temperature",null],
 ["Pince","Lenti garázs",null,null]
 ]};
const STYLE=`:host{display:block;min-width:0;color:#f2f8ff;font:500 15px/1.35 system-ui,-apple-system,"Segoe UI",sans-serif}*{box-sizing:border-box}.root{background:radial-gradient(ellipse at 50% -20%,#163753 0%,#091a2b 55%,#041321 100%);padding:clamp(12px,1.7vw,27px);min-height:calc(100vh - 96px);border:1px solid #183c59;border-radius:23px}.heading{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap;padding:6px 8px 21px;border-bottom:1px solid #244762;margin-bottom:17px}h1{font-size:clamp(26px,3vw,44px);letter-spacing:-.045em;margin:0;font-weight:850}h2{font-size:21px;margin:10px 0 12px;color:#68d8fb}.sub{color:#93bbd4;font-size:13px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:15px}.tile{position:relative;background:linear-gradient(145deg,#102e49,#082037);border:1px solid #2775a3;border-radius:15px;padding:17px;min-width:0;box-shadow:inset 0 1px #ffffff11,0 5px 24px #0003}.tile.hot{background:linear-gradient(145deg,#4c232e,#1a1d2e);border-color:#fa4d57;box-shadow:inset 0 0 32px #ed48551c,0 0 15px #ff303025}.interactive{cursor:pointer}.interactive:hover{border-color:#6ad8ff;filter:brightness(1.12)}.name{font-weight:750;font-size:clamp(14px,1.35vw,20px)}.value{font-size:clamp(26px,3.4vw,51px);font-weight:850;letter-spacing:-.04em;margin:13px 0;white-space:nowrap;line-height:1.08;font-variant-numeric:tabular-nums}.row{display:flex;justify-content:space-between;align-items:center;gap:12px;min-width:0}.row>div{min-width:0}.level{border:1px solid #185478;background:#061b2d99;border-radius:14px;margin:12px 0;padding:12px}.level h2{margin:0 0 12px}.tag{font-size:12px;color:#9ac2dd}.warn{color:#ff968b}.roomtemp{font-size:clamp(27px,2.5vw,38px);line-height:1.16;font-variant-numeric:tabular-nums;white-space:nowrap;margin:12px 0 3px;font-weight:850}.requested{font-size:16px;white-space:nowrap;font-variant-numeric:tabular-nums}.roomcard{min-height:139px}.roomcard .name{font-size:16px}.roomcard.hot .tag:last-child{color:#ff8e83;font-size:14px;font-weight:800}.roomcard .tag:last-child{font-size:13px;font-weight:700}.rooms-layout{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(310px,1fr);gap:15px}.detail{position:sticky;top:12px;align-self:start;min-height:480px;background:linear-gradient(160deg,#09243d,#071a2a);border:1px solid #2389bd;border-radius:18px;padding:22px}.dial{width:min(290px,90%);aspect-ratio:1;border:14px solid #288cde;border-right-color:#ec5659;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;margin:20px auto;box-shadow:0 0 30px #168dfb35,inset 0 0 28px #168dfb20}.dial strong{font-size:clamp(30px,3vw,48px)}.detail .stepper{margin:10px auto 19px}.detail .stepper button{border-radius:50%;width:55px;height:55px;font-size:29px;padding:0;touch-action:manipulation}.detail .stepper strong{font-size:25px;min-width:105px;text-align:center}.mode-row{display:flex;gap:7px;flex-wrap:wrap;justify-content:center}.mode-row span{flex:1;text-align:center;background:#103452;border:1px solid #286f9a;border-radius:10px;padding:11px 5px;font-size:12px}.summary{display:flex;flex-direction:column;gap:11px}.summary .tile{min-height:81px}.home-layout{display:grid;grid-template-columns:minmax(0,2fr) minmax(255px,.9fr);gap:16px}.home-circuits{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:13px}.home-circuits>.tile{grid-column:span 2;min-height:196px}.home-circuits>.tile:nth-child(-n+2){grid-column:span 3;min-height:228px}.banner{margin-top:15px;border:1px solid #267aac;background:linear-gradient(100deg,#082a43,#103c56,#061a2c);border-radius:16px;padding:21px}.diagram{overflow:auto;border:1px solid #36566c;border-radius:15px;background:#0c2030}.diagram svg{display:block;width:100%;min-width:780px}.pipe-hot{stroke:#ed725a;stroke-width:10;fill:none}.pipe-cold{stroke:#25a5ee;stroke-width:10;fill:none}.controls{display:flex;gap:10px;flex-wrap:wrap;margin-top:15px}button{font:inherit;color:#eaf5ff;background:#16496e;border:1px solid #349bce;border-radius:9px;padding:9px 15px;cursor:pointer}.overlay{position:fixed;inset:0;background:#02070bdd;display:grid;place-items:center;z-index:100;padding:20px}.modal{background:#152d40;border:1px solid #54758a;border-radius:20px;padding:24px;width:min(470px,100%)}.stepper{display:flex;gap:16px;justify-content:center;align-items:center;margin:24px 0}.stepper strong{font-size:34px}@media(max-width:980px){.rooms-layout,.home-layout{grid-template-columns:1fr}.detail{position:static}.grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:600px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.home-circuits>.tile,.home-circuits>.tile:nth-child(-n+2){grid-column:span 3}.stats{grid-template-columns:repeat(2,1fr)}.root{padding:10px}.roomcard{min-height:130px}.roomtemp{font-size:25px}}`;
class FutestuningCard extends HTMLElement {
 setConfig(cfg){this.cfg={view:"home",...cfg};if(!["home","plant","rooms"].includes(this.cfg.view))throw Error("Invalid view");if(!this.shadowRoot){this.attachShadow({mode:"open"});this.shadowRoot.innerHTML="<style>"+STYLE+"</style><div id='root'></div>"}this.render()}
 set hass(v){this._hass=v;this.render()}
 get hass(){return this._hass}
 s(id){return this._hass?.states?.[id]}
 on(id){return this.s(id)?.state==="on"}
 fmt(id){const v=this.s(id)?.state,n=Number(v);return v!==undefined&&v!=="unavailable"&&v!=="unknown"&&Number.isFinite(n)&&n>-100?n.toFixed(1).replace(".",",")+" °C":"—"}
 target(id){const raw=this.s(id)?.attributes?.temperature;const n=Number(raw);return raw!==undefined&&raw!==null&&Number.isFinite(n)?n.toFixed(1).replace(".",",")+" °C":"—"}
 heatState(id){const st=this.s(id);if(!st||["unknown","unavailable"].includes(st.state))return null;const a=st.attributes||{};if(a.hvac_action==="heating")return true;if(["idle","off","cooling","dry","fan"].includes(a.hvac_action)||st.state==="off")return false;return null}
 heatLabel(v){return v===true?"♨ Fűt":v===false?"◯ Nem fűt":"◌ Állapot ismeretlen"}
  roomClimate(r){if(r[3]&&this.s(r[3]))return r[3];const name=r[1].toLocaleLowerCase("hu").replace(/\s+/g," ").trim();const matches=Object.entries(this._hass?.states||{}).filter(([id,v])=>{if(!id.startsWith("climate."))return false;const label=String(v.attributes?.friendly_name||"").toLocaleLowerCase("hu").replace(/\s+/g," ").trim();return label===name||label===name+" radiátor"||label===name+" termosztát"});return matches.length===1?matches[0][0]:null}
 async adjustRoomTemperature(id,delta){const st=this.s(id),a=st?.attributes||{};const cur=a.temperature;if(cur===undefined||cur===null||!Number.isFinite(Number(cur)))return;const min=Number.isFinite(Number(a.min_temp))?Number(a.min_temp):5,max=Number.isFinite(Number(a.max_temp))?Number(a.max_temp):35,step=Number(a.target_temp_step)||0.5;const next=Math.max(min,Math.min(max,Math.round((Number(cur)+delta*step)*100)/100));if(next===Number(cur))return;try{await this._hass.callService("climate","set_temperature",{entity_id:id,temperature:next})}catch(e){console.warn("Fűtéstuning: termosztát állítás sikertelen",e)}}
 heading(){return this.cfg.view==="home"?"Főoldal":this.cfg.view==="plant"?"Kazánház":"Helyiségek"}
 render(){if(!this.shadowRoot||!this._hass)return;const r=this.shadowRoot.getElementById("root");r.innerHTML=`<div class="root"><div class="heading"><div><h1>♨ Fűtés · ${this.heading()}</h1><div class="sub">TECH · SONOFF · Home Assistant</div></div><span class="tag">Fűtéstuning</span></div>${this.cfg.view==="home"?this.home():this.cfg.view==="plant"?this.plant():this.rooms()}</div>`;r.querySelectorAll("[data-step]").forEach(e=>e.addEventListener("click",()=>{const id=e.dataset.climate;this.adjustRoomTemperature(id,Number(e.dataset.step))}));r.querySelectorAll("[data-room]").forEach(e=>e.addEventListener("click",()=>{this.selectedRoom=e.dataset.room;this.render()}));r.querySelectorAll("[data-target]").forEach(e=>e.addEventListener("click",()=>this.editTarget(+e.dataset.target)));r.querySelectorAll("[data-climate]").forEach(e=>e.addEventListener("click",()=>this.dispatchEvent(new CustomEvent("hass-more-info",{detail:{entityId:e.dataset.climate},bubbles:true,composed:true}))))}
 home(){const active=DATA.circuits.filter(c=>this.on(c[3])).length;return `<div class="home-layout"><div><div class="home-circuits">${DATA.circuits.map((c,i)=>this.circuit(c,i)).join("")}<div class="tile"><div class="name">💧 HMV</div><div class="value">—</div><div class="sub">Hőmérséklet-érzékelő nincs bekötve</div><div class="tag">Külön vezérlés</div></div><div class="tile"><div class="name">⌂ Hozzáépítés</div><div class="value">2 alkör</div><div class="sub">Garázs és háló · Computherm</div><div class="tag">Önálló vezérlés</div></div></div></div><aside class="tile summary"><h2>▥ Rendszer összegzés</h2><div class="tile"><div class="tag">Puffer hőmérséklet</div><div class="value">${this.fmt(DATA.buffer)}</div></div><div class="tile"><div class="tag">Összes hőigény</div><div class="value ${active?"warn":""}">${active} aktív</div></div><div class="tile"><div class="tag">TECH</div><div class="name">3 fűtési kör</div><div class="tag">Élő adatkapcsolat · nem fizikai hibajelzés</div></div><div class="tile"><div class="tag">HMV állapot</div><div class="name">Nincs szonda</div></div><div class="tile"><div class="tag">Külső érzékelő</div><div class="name">Nincs bekötve</div></div></aside></div><div class="banner"><h2>♧ Kazánházi séma</h2><div class="sub">Puffer, TECH-vezérlés, fűtési körök és visszatérő vezetékek</div><div class="tag">A Kazánház fület választva megnyitható a részletes rendszerrajz.</div></div>`}
 circuit(c,i){const hot=this.on(c[3]);return `<div class="tile interactive ${hot?"hot":""}" data-target="${i}"><div class="name">${c[0]}</div><div class="value">${this.fmt(c[1])}</div><div class="sub">Cél: ${this.fmt(c[2])}</div><div class="tag ${hot?"warn":""}">${hot?"● Hőigény":"○ Nincs hőigény"} · célérték állítható</div></div>`}
 rooms(){const levels=["Emelet","Földszint","Pince"];const selected=DATA.rooms.find(r=>r[1]===this.selectedRoom)||DATA.rooms[0];const current=selected[2]?this.fmt(selected[2]):"—";const climate=this.roomClimate(selected);const selectedHeating=this.heatState(climate);return `<div class="rooms-layout"><div>${levels.map(level=>`<section class="level"><h2>${level} <span class="tag">· ${DATA.rooms.filter(r=>r[0]===level).length} helyiség</span></h2><div class="grid">${DATA.rooms.filter(r=>r[0]===level).map(r=>{const roomCtl=this.roomClimate(r),cs=this.s(roomCtl),heat=this.heatState(roomCtl),actual=r[2]?this.fmt(r[2]):Number.isFinite(Number(cs?.attributes?.current_temperature))?Number(cs.attributes.current_temperature).toFixed(1)+" °C":"—";return `<div class="tile roomcard interactive ${heat?"hot":""}" data-room="${r[1]}"><div class="name">${r[1]} ›</div><div class="row"><div class="roomtemp">${actual}</div><b class="requested">${roomCtl?this.target(roomCtl):"—"}</b></div><div class="tag">Mért · Kért</div><div class="tag ${heat===true?"warn":""}">${this.heatLabel(heat)}</div></div>`}).join("")}</div></section>`).join("")}</div><aside class="detail"><h2>${selected[1]}</h2><div class="sub">${selected[0]} · ${this.heatLabel(selectedHeating)}</div><div class="dial"><div class="tag">Jelenlegi hőmérséklet</div><strong>${current}</strong><div class="tag">Beállított</div><div class="name">${climate?this.target(climate):"—"}</div></div>${climate?`<div class="stepper"><button data-step="-1" data-climate="${climate}" aria-label="Célhőmérséklet csökkentése">−</button><strong>${this.target(climate)}</strong><button data-step="1" data-climate="${climate}" aria-label="Célhőmérséklet növelése">+</button></div>`:`<div class="sub" style="text-align:center">Nem elérhető a helyiség célhőmérséklete a Home Assistantban.</div>`}<div class="mode-row"><span>Eco</span><span>Komfort</span><span>Éjszaka</span><span>Távollét</span></div><div class="banner"><div class="name">Termosztát</div><div class="sub">${climate?"Az alábbi gomb megnyitja a Home Assistant termosztátját.":"Ehhez a helyiséghez még nincs megbízhatóan azonosított vezérlő."}</div>${climate?`<button data-climate="${climate}">Termosztát megnyitása</button>`:""}</div><div class="banner"><div class="name">Klíma</div><div class="sub">A Gree entitás hozzárendelése még ellenőrzendő; hamis vezérlést nem jelenítünk meg.</div></div></aside></div>`}
 plant(){const C=DATA.circuits;const cells=C.map((c,i)=>{const x=420+i*255;return `<g><path d="M${x+100} 260 V313" stroke="#ff775c" stroke-width="10"/><path d="M${x+120} 445 V535" stroke="#35b5ff" stroke-width="10"/><rect x="${x}" y="314" rx="14" width="230" height="129" fill="#102c45" stroke="#2687b9"/><text x="${x+15}" y="343" fill="#68d9fb" font-size="20" font-weight="700">0${i+1} · ${c[0]}</text><text x="${x+15}" y="389" fill="white" font-size="31" font-weight="800">${this.fmt(c[1])}</text><text x="${x+15}" y="422" fill="#adcfdf" font-size="17">Cél: ${this.fmt(c[2])}</text><circle cx="${x+105}" cy="472" r="18" stroke="#7cf3b0" stroke-width="4" fill="#0c3040"/><path d="M${x+105} 459 L${x+116} 479 L${x+94} 479 Z" fill="#7cf3b0"/><text x="${x+132}" y="478" fill="#b6d1de" font-size="16">P${i+1} · állapot: nincs adat</text></g>`}).join("");return `<div class="tile" style="margin-bottom:14px"><div class="row"><div><h2>♨ Kazánház · gépészeti áttekintés</h2><div class="sub">ATTACK → puffer → TECH három fűtőkör → visszatérő ág</div></div><div class="tag">Adatmegjelenítés · közvetlen szivattyúvezérlés nélkül</div></div></div><div class="grid" style="margin-bottom:14px"><div class="tile"><div class="name">Hőforrás / puffer</div><div class="value">${this.fmt(DATA.buffer)}</div><div class="tag">TH Elite · egyetlen mért pufferhőmérséklet</div></div><div class="tile"><div class="name">TECH EU-i-3 PLUS OT</div><div class="value">3 kör</div><div class="tag">Pince · Padlófűtés · Radiátor</div></div><div class="tile"><div class="name">HMV · Hozzáépítés</div><div class="value">— / 2</div><div class="tag">HMV nincs szonda · hozzáépítés külön vezérlés</div></div></div><div class="diagram"><svg viewBox="0 0 1360 610" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Pufferből induló fűtési körök és visszatérő vezetékek"><defs><linearGradient id="fttank" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#a33b48"/><stop offset=".52" stop-color="#714d77"/><stop offset="1" stop-color="#205c97"/></linearGradient><filter id="ftglow"><feGaussianBlur stdDeviation="3" result="blur"/><feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs><rect x="18" y="110" width="175" height="330" rx="16" fill="#132a3d" stroke="#3785b2"/><text x="41" y="153" fill="#65d9ff" font-size="24" font-weight="700">Hőforrás</text><text x="41" y="199" fill="white" font-size="25">ATTACK</text><text x="41" y="230" fill="#a9c4d8" font-size="18">PROFI PID</text><text x="41" y="365" fill="#a9c4d8" font-size="17">Kazánszivattyú</text><text x="41" y="398" fill="#f3fbff" font-size="19">állapot: —</text><rect x="224" y="115" width="142" height="320" rx="40" fill="url(#fttank)" stroke="#6ca7cc" stroke-width="3"/><text x="245" y="165" fill="white" font-size="26" font-weight="750">Puffer</text><text x="237" y="217" fill="white" font-size="28" font-weight="800">${this.fmt(DATA.buffer)}</text><text x="241" y="250" fill="#d4e6f3" font-size="16">TH Elite</text><text x="235" y="377" fill="#d4e6f3" font-size="16">1 mérési pont</text><path d="M193 160 H224 M366 260 H1245" stroke="#ff795f" stroke-width="11" fill="none" filter="url(#ftglow)"/><path d="M1245 535 H366 V410" stroke="#26b2ff" stroke-width="11" fill="none" filter="url(#ftglow)"/><path d="M224 410 H193" stroke="#26b2ff" stroke-width="9"/><text x="408" y="242" fill="#ffb29c" font-size="21">Előremenő főág →</text><text x="408" y="569" fill="#7bd1ff" font-size="21">← Visszatérő főág</text>${cells}<rect x="1210" y="314" width="130" height="129" rx="12" fill="#102c45" stroke="#2687b9"/><text x="1223" y="344" fill="#70d8fb" font-size="19">HMV</text><text x="1223" y="374" fill="white" font-size="17">Nincs szonda</text><text x="1223" y="400" fill="#a9c4d8" font-size="15">Külön vezérlés</text><rect x="770" y="25" width="555" height="100" rx="15" fill="#102b44" stroke="#3788b3"/><text x="792" y="67" fill="#70d8fb" font-size="25" font-weight="750">TECH vezérlés · három kör</text><text x="792" y="100" fill="#a9c4d8" font-size="17">Szivattyúkimeneti visszajelzés még nem elérhető</text></svg></div><div class="grid" style="margin-top:13px"><div class="tile"><h2>Működési logika</h2><div class="sub">A TECH vezérli a három szivattyút. A kártya az előremenő hőfokokat és a hőigényeket figyeli; a tényleges szivattyúkimenet nem ismert.</div></div><div class="tile"><h2>Jelmagyarázat</h2><div class="sub">🔴 Meleg előremenő · 🔵 visszatérő · zöld szivattyúikon: jelképes, nem működés-visszajelzés</div></div><div class="tile"><h2>Hozzáépítés</h2><div class="sub">Külön hidraulikus kör, Computherm-vezérléssel. Garázs és háló. HMV: külön vezérlés, hőmérő nélkül.</div></div></div><div class="controls">${C.map((c,i)=>`<button data-target="${i}">${c[0]} · célhőmérséklet</button>`).join("")}</div>`}
 editTarget(i){const c=DATA.circuits[i],state=this.s(c[2]);if(!state)return;let val=Number(state.state),min=Number(state.attributes?.min??10),max=Number(state.attributes?.max??80),step=Number(state.attributes?.step??1);if(!Number.isFinite(val))return;const overlay=document.createElement("div");overlay.className="overlay";overlay.innerHTML=`<div class="modal"><div class="row"><h2>${c[0]} célhőmérséklet</h2><button id="close">✕</button></div><div class="sub">Csak a TECH célértékét módosítja.</div><div class="stepper"><button id="minus">−</button><strong id="temp"></strong><button id="plus">+</button></div><button id="save" style="width:100%">Mentés</button></div>`;this.shadowRoot.append(overlay);const close=()=>overlay.remove(),refresh=()=>overlay.querySelector("#temp").textContent=val.toFixed(1).replace(".",",")+" °C";refresh();overlay.querySelector("#close").onclick=close;overlay.querySelector("#minus").onclick=()=>{val=Math.max(min,+(val-step).toFixed(2));refresh()};overlay.querySelector("#plus").onclick=()=>{val=Math.min(max,+(val+step).toFixed(2));refresh()};overlay.querySelector("#save").onclick=async()=>{let b=overlay.querySelector("#save");b.disabled=true;try{await this._hass.callService("number","set_value",{entity_id:c[2],value:val});close()}catch(e){b.disabled=false;b.textContent="Hiba – újrapróbálás"}}}
 getCardSize(){return 8}
}
if(!customElements.get("futestuning-card"))customElements.define("futestuning-card",FutestuningCard);
window.customCards=window.customCards||[];
window.customCards.push({type:"futestuning-card",name:"Fűtéstuning",description:"Háromnézetes fűtés áttekintő"});
